import {makeRover,decorateSurface} from './expedition-kit.js';
import {obscuration} from './expedition-math.js';
import * as T from './assets/three.module.js';
import {makeStars,makeSatellite} from './spacefx.js';
import {sceneNavigation} from './scene-navigation.js';
import {hohmann,orbitalElements,dateDays,position,AU,kepler} from './dynamics.js';
import {clamp,eclipseState,propellantFraction,surfaceHeight,slopeAt} from './expedition-math.js';
const $=s=>document.querySelector(s),fmt=(n,d=2)=>n.toLocaleString('en-US',{maximumFractionDigits:d});
export function setupExpeditions(api,gfx){
 const section=document.createElement('section');section.id='expeditions';section.className='wrap expedition-section';section.innerHTML=`<div class="section-heading"><div><span class="eyebrow">EXPERIMENTAL INSTRUMENTS / 05</span><h2>EXPEDITION <em>STUDIO.</em></h2></div><p>Go below the surface. Design a departure.<br>Explore light, structure, and terrain.</p></div><div class="workspace"><div class="workspace-modes" role="group" aria-label="Expedition tool">${[['surface','Surface descent'],['interior','Planetary interiors'],['mission','Mission designer'],['eclipse','Eclipse laboratory']].map(([id,label],i)=>`<button data-expedition="${id}" aria-pressed="${i===0}">${label}</button>`).join('')}</div><div class="workspace-grid"><div class="expedition-visual"><div id="expedition-render" tabindex="0" aria-label="Interactive expedition scene. Drag to orbit and use plus or minus to zoom." role="img"></div><div id="expedition-status" role="status"></div><div class="scene-actions"><button id="expedition-reset">Reset camera</button><button id="expedition-play" aria-pressed="false">Play experiment</button></div></div><div id="expedition-controls" class="workspace-config"></div></div></div><p class="source-note">Sources: <a href="https://science.nasa.gov/earth/facts/" target="_blank" rel="noopener">NASA planetary structure</a> · <a href="https://science.nasa.gov/eclipses/geometry/" target="_blank" rel="noopener">eclipse geometry</a> · <a href="https://ssd.jpl.nasa.gov/astro_par.html" target="_blank" rel="noopener">JPL constants</a>. Approximation and scale notes accompany each tool.</p>`;
 $('#field-lab').after(section);const navLink=document.createElement('a');navLink.href='#expeditions';navLink.textContent='Expeditions';document.querySelector('.header nav').append(navLink);
 let mode=['surface','interior','mission','eclipse'].includes(new URLSearchParams(location.search).get('instrument'))?new URLSearchParams(location.search).get('instrument'):'surface',running=false,phase=0,visible=false,renderer,scene,camera,nav,keyLight,surfaceExtras;
 const state={lat:23,lon:13,x:0,z:0,view:'drone',slice:0,layer:0,departure:2,arrival:3,date:'2026-11-12',bend:0,height:0,isp:450,dryMass:5000,sunElevation:35,explode:0,opacity:1,offset:0,moonDistance:3.5,observer:false};
 const controls=$('#expedition-controls'),root=$('#expedition-render');
 try{renderer=gfx.rendererFor(root);renderer.localClippingEnabled=true;scene=new T.Scene();scene.background=new T.Color(0x080a0d);camera=new T.PerspectiveCamera(44,1,.01,500);gfx.observeSize(root,renderer,camera);keyLight=gfx.addLights(scene);renderer.shadowMap.enabled=innerWidth>760;renderer.shadowMap.type=T.PCFSoftShadowMap;keyLight.castShadow=innerWidth>760;keyLight.shadow.mapSize.set(2048,2048);keyLight.shadow.camera.left=keyLight.shadow.camera.bottom=-18;keyLight.shadow.camera.right=keyLight.shadow.camera.top=18;keyLight.shadow.camera.far=70;scene.add(new T.AmbientLight(0xc9bdab,.55),makeStars(1200,100));nav=sceneNavigation(root,camera,{distance:12,pitch:.4,yaw:.4});}catch(error){root.innerHTML='<p class="fallback-message">3D unavailable. The instrument controls and numerical results remain available.</p>';}
 let group=new T.Group(),terrain,rover,globe,disks=[],shells=[],clipPlane=new T.Plane(new T.Vector3(-1,0,0),0),craft,curve,reference,handle,elapsed=0,visualTime=0,last=0,seed=0,dragging=false;
 if(scene)scene.add(group);
 const range=(id,label,min,max,step,value)=>`<label>${label}<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
 const options=api.planets.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('');
 function dispose(){group.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose())});group.clear();disks=[];shells=[];rover=null;surfaceExtras=null;}
 function line(points,color=0xd2b482){const obj=new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color,transparent:true,opacity:.8}));group.add(obj);return obj;}
 function mesh(g,color){const m=new T.Mesh(g,new T.MeshStandardMaterial({color,roughness:.85,metalness:.15}));group.add(m);return m;}
 function readout(rows,note){$('#expedition-readout').innerHTML=rows.map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('');$('#expedition-note').textContent=note;}
 function renderControls(){
  running=false;phase=0;$('#expedition-play').setAttribute('aria-pressed',false);$('#expedition-play').textContent='Play experiment';
  if(mode==='surface')controls.innerHTML=`<span class="eyebrow">LANDING SITE / ${api.planets[api.getState().current].name}</span>${range('landing-lat','Target latitude / °',-80,80,.1,state.lat)}${range('landing-lon','Target longitude / °',-180,180,.1,state.lon)}<button id="begin-descent" class="primary">Begin orbital descent ↘</button><label>Surface camera<select id="surface-camera"><option value="drone">Drone / orbit</option><option value="rover">Rover / ground level</option></select></label>${range('surface-x','Explore east / west · local km',-8,8,.1,state.x)}${range('surface-z','Explore north / south · local km',-8,8,.1,state.z)}<button id="surface-drive" class="secondary-action">Drive east →</button>`;
  if(mode==='interior')controls.innerHTML=`<span class="eyebrow">${api.planets[api.getState().current].name} / STRUCTURAL MODEL</span>${range('interior-slice','Cutting plane / normalized radius',-.95,.95,.01,state.slice)}<label>Inspect layer<select id="interior-layer"></select></label><p class="workspace-note">Drag the view to inspect the section from any angle.</p>`;
  if(mode==='mission')controls.innerHTML=`<div class="pair"><label>Departure<select id="mission-from">${options}</select></label><label>Arrival<select id="mission-to">${options}</select></label></div><label>Launch date<input id="mission-date" type="date" min="1800-01-01" max="2048-01-01" value="${state.date}"></label>${range('mission-bend','Maneuver point / radial offset',-3,3,.05,state.bend)}${range('mission-height','Maneuver point / out-of-plane',-3,3,.05,state.height)}${range('mission-isp','Engine specific impulse / s',200,900,10,state.isp)}<button id="mission-baseline" class="secondary-action">Restore Hohmann reference</button><p class="workspace-note">Drag the amber maneuver point, or use the two maneuver sliders. Amber is a geometric design sketch; pale green is the physical reference.</p>`;
  if(mode==='eclipse')controls.innerHTML=`${range('eclipse-offset','Moon alignment / lateral offset',-2,2,.01,state.offset)}${range('eclipse-distance','Moon distance / scene units',2,5,.01,state.moonDistance)}<div class="scene-actions"><button id="eclipse-total">Total alignment</button><button id="eclipse-annular">Annular alignment</button></div><label>Camera<select id="eclipse-camera"><option value="geometry">Geometry / system</option><option value="observer">Surface observer / look at Sun</option></select></label>`;
  controls.insertAdjacentHTML('afterbegin','<label class="expedition-world-label">Instrument world<select id="expedition-world">'+options+'</select></label>');$('#expedition-world').value=api.getState().current;
  if(mode==='surface')controls.insertAdjacentHTML('beforeend', '<div class="surface-upgrades"><label>Sun elevation / °<input id="surface-sun" type="range" min="5" max="85" value="'+state.sunElevation+'"></label><label><input id="surface-lidar" type="checkbox" checked> Lidar sweep</label><label><input id="surface-rocks" type="checkbox" checked> Surface rocks</label><label><input id="surface-tracks" type="checkbox" checked> Rover tracks</label><label><input id="surface-lights" type="checkbox"> Headlights</label><div class="scene-actions"><button data-drive="north">North ↑</button><button data-drive="south">South ↓</button><button data-drive="west">West ←</button><button data-drive="east">East →</button></div></div>');
  if(mode==='interior')controls.insertAdjacentHTML('beforeend',range('interior-explode','Exploded layers',0,1,.01,state.explode)+range('interior-opacity','Shell opacity',.15,1,.01,state.opacity));
  if(mode==='mission')controls.insertAdjacentHTML('beforeend',range('mission-dry-mass','Dry spacecraft mass / kg',500,50000,500,state.dryMass)+'<button id="mission-scan" class="secondary-action">Scan next 780 launch dates ↗</button>');
  controls.insertAdjacentHTML('beforeend','<div id="expedition-readout" class="workspace-readout" aria-live="polite"></div><p id="expedition-note" class="workspace-note"></p>');
  if(mode==='mission'){$('#mission-from').value=state.departure;$('#mission-to').value=state.arrival;}
  if(mode==='surface')$('#surface-camera').value=state.view;
  build();nav?.reset(mode==='surface'?17:mode==='interior'?8:17);
 }
 function layers(){const i=api.getState().current;return i<4?[['Crust',1,0x746b59,'Silicate rock'],['Mantle',.97,0xa56842,'Hot silicate rock'],['Outer core',.55,0xd99f55,'Metal-rich interior'],['Inner core',.19,0xf1d49a,'Dense central region']]:i<6?[['Cloud envelope',1,0xc4b18e,'Hydrogen / helium'],['Deep envelope',.8,0x9f7959,'Compressed fluid'],['Conducting interior',.52,0xc89e6b,'High-pressure hydrogen-rich model'],['Central region',.2,0xebd6a7,'Model-dependent heavy-element enrichment']]:[['Atmosphere',1,0x8eb3b2,'Hydrogen / helium / methane'],['Deep fluid',.76,0x588b91,'High-pressure volatile-rich model'],['Rock-rich interior',.35,0xa18568,'Model-dependent central region']];}
 function build(){
  dispose();if(scene){scene.fog=mode==='surface'?new T.FogExp2(0x242627,.035):null;scene.background.set(mode==='surface'?0x242627:0x080a0d);}const p=api.planets[api.getState().current];
  if(mode==='surface'){
   if(api.getState().current>3){const view=gfx.world(p,96);view.group.scale.setScalar(2.6);group.add(view.group);$('#expedition-status').textContent='ATMOSPHERIC WORLD / no solid surface';readout([['WORLD',p.name],['SURFACE','Atmospheric reference level'],['LANDING','Select Mercury, Venus, Earth or Mars']], 'Gas and ice giants have no solid landing surface in this model. Select a rocky world for the rover and terrain tools.');return;}
   seed=(state.lat+state.lon)*.02;const g=new T.PlaneGeometry(32,32,innerWidth<760?110:220,innerWidth<760?110:220);g.rotateX(-Math.PI/2);const a=g.attributes.position,colors=[];for(let i=0;i<a.count;i++){const h=surfaceHeight(a.getX(i),a.getZ(i),seed);a.setY(i,h);const c=new T.Color(api.getState().current===3?0xa56e50:0x777765).multiplyScalar(.75+(h+1)*.2);colors.push(c.r,c.g,c.b)}g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.computeVertexNormals();terrain=new T.Mesh(g,new T.MeshStandardMaterial({vertexColors:true,roughness:1}));group.add(terrain);
   rover=makeRover();group.add(rover);surfaceExtras=decorateSurface(group,terrain,seed);const ring=new T.Mesh(new T.RingGeometry(.7,.72,64),new T.MeshBasicMaterial({color:0xd5b17a,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(state.x,surfaceHeight(state.x,state.z,seed)+.03,state.z);group.add(ring);updateSurface();
  }
  if(mode==='interior'){
   const data=layers();$('#interior-layer').innerHTML=data.map((l,i)=>`<option value="${i}">${l[0]}</option>`).join('');state.layer=Math.min(state.layer,data.length-1);$('#interior-layer').value=state.layer;
   data.forEach((l,i)=>{const m=new T.Mesh(new T.SphereGeometry(l[1]*2,64,40),new T.MeshStandardMaterial({color:l[2],roughness:.8,clippingPlanes:[clipPlane],side:T.DoubleSide}));group.add(m);shells.push(m);const disk=new T.Mesh(new T.CircleGeometry(1,96),new T.MeshBasicMaterial({color:l[2],side:T.DoubleSide}));disk.rotation.y=Math.PI/2;group.add(disk);disks.push(disk)});updateInterior();
  }
  if(mode==='mission')buildMission();
  if(mode==='eclipse')buildEclipse();
  $('#expedition-status').textContent=mode==='surface'?'ILLUSTRATIVE LANDING TERRAIN':mode==='interior'?'SCHEMATIC INTERIOR / NOT TOMOGRAPHY':mode==='mission'?'HELIOCENTRIC DESIGN / TWO-BODY REFERENCE':'SCALED ECLIPSE GEOMETRY';
 }
 function updateSurface(){const p=api.planets[api.getState().current];if(rover)rover.position.set(state.x,surfaceHeight(state.x,state.z,seed),state.z);readout([['SITE',`${fmt(state.lat,1)}° / ${fmt(state.lon,1)}°`],['LOCAL POSITION',`${fmt(state.x)} / ${fmt(state.z)} km`],['LOCAL SLOPE',fmt(slopeAt(state.x,state.z,seed),1)+'°'],['LANDING FOOTPRINT','1.4 km diameter / illustrative'],['TRAVERSE SPEED',running?'0.4 km/s · accelerated':'Stopped']],p.name+' site coordinates guide the orbital camera; this local geology is generated, not mapped elevation. Rover scale and traversal speed are illustrative. Solid-surface descent is available for rocky planets only.');}
 function updateInterior(){const x=state.slice*2;clipPlane.constant=x;layers().forEach((l,i)=>{const radius=l[1]*2,r=Math.sqrt(Math.max(0,radius*radius-x*x));disks[i].visible=r>0;disks[i].scale.setScalar(r);disks[i].position.set(x+.004+i*.001,0,0);shells[i].position.x=i*state.explode*.7;disks[i].position.x+=i*state.explode*.7;shells[i].material.clippingPlanes=[new T.Plane(new T.Vector3(-1,0,0),x+i*state.explode*.7)];shells[i].material.transparent=state.opacity<1;shells[i].material.opacity=state.opacity;shells[i].material.emissive.setHex(i===state.layer?0x221507:0)});const l=layers()[state.layer],depth=(1-l[1])*api.planets[api.getState().current].diameter/2;const earth=api.getState().current===2;readout([['LAYER',l[0]],['COMPOSITION',l[3]],['MODEL BOUNDARY DEPTH',fmt(depth,0)+' km'],['THERMAL REGIME',earth?fmt(288+5712*(1-l[1])**.65,0)+' K / illustrative profile':'Not quantified / uncertain model'],['PRESSURE',earth?fmt(360*(1-l[1])**1.7,1)+' GPa / illustrative profile':'Not quantified / uncertain model']], 'Layer radii are schematic and exaggerated for inspection. Earth pressure and temperature use a toy interpolation (center: 360 GPa / 6000 K); these are not measured profiles. Giant interiors are model-dependent.');}
 function buildMission(){const a=state.departure,b=state.arrival;if(a===b){readout([['SELECT DISTINCT WORLDS','Departure and arrival must differ']],'No transfer calculated.');curve=null;return;}const r1=orbitalElements(a)[0],r2=orbitalElements(b)[0],h=hohmann(r1,r2),scale=5/Math.max(r1,r2),days=dateDays(state.date),p=position(a,days),angle=Math.atan2(p.z,p.x);const rotate=v=>v.applyAxisAngle(new T.Vector3(0,1,0),-angle);
  for(const r of [r1,r2])line(Array.from({length:181},(_,i)=>new T.Vector3(Math.cos(i/180*Math.PI*2)*r*scale,0,Math.sin(i/180*Math.PI*2)*r*scale)),0x575c58);
  const referencePoints=Array.from({length:100},(_,i)=>rotate(new T.Vector3(((r1+r2)/2*Math.cos(i/99*Math.PI)+(r1-r2)/2)*scale,0,Math.sqrt(r1*r2)*Math.sin(i/99*Math.PI)*scale)));reference=line(referencePoints,0x8baca0);
  const start=referencePoints[0],end=referencePoints.at(-1),mid=rotate(new T.Vector3(state.bend,state.height,Math.sqrt(r1*r2)*scale));curve=new T.QuadraticBezierCurve3(start,mid.clone().multiplyScalar(2).sub(start.clone().add(end).multiplyScalar(.5)),end);if(Math.abs(state.bend)+Math.abs(state.height)<.0001){curve=new T.Curve();curve.getPoint=t=>{const e=(r2-r1)/(r2+r1),E=kepler(t*Math.PI,e);return rotate(new T.Vector3(((r1+r2)/2*Math.cos(E)+(r1-r2)/2)*scale,0,Math.sqrt(r1*r2)*Math.sin(E)*scale));};}line(curve.getPoints(120));handle=mesh(new T.SphereGeometry(.13,16,12),0xffcf85);handle.position.copy(mid);handle.userData.maneuver=true;craft=makeSatellite();craft.scale.setScalar(2);group.add(craft);craft.position.copy(start);mesh(new T.SphereGeometry(.15,24,16),0xd9b57a);
  for(const [index,at] of [[a,start],[b,end]]){const model=gfx.world(api.planets[index],32);model.group.scale.setScalar(.16);model.group.position.copy(at);model.atmosphere.visible=false;group.add(model.group);}
  const target=position(b,days+h.seconds/86400),ideal=end.clone().divideScalar(scale),miss=ideal.distanceTo(new T.Vector3(target.x,target.y,target.z))*AU;readout([['REFERENCE FLIGHT TIME',fmt(h.seconds/86400,1)+' days'],['REFERENCE Δv',fmt(h.departure+h.arrival,3)+' km/s'],['IDEAL PROPELLANT FRACTION',fmt(propellantFraction(h.departure+h.arrival,state.isp)*100,1)+'%'],['REFERENCE PROPELLANT MASS',fmt(state.dryMass*(1/(1-propellantFraction(h.departure+h.arrival,state.isp))-1),0)+' kg'],['ARRIVAL POSITION MISMATCH',fmt(miss/1e6,1)+' million km']], 'Pale green: circular, coplanar Hohmann reference. Amber: editable geometric sketch, not a solved thrust trajectory. Time, Δv and rocket-equation fuel fraction apply only to the reference. Date rotates departure and compares the approximate target position; no rendezvous optimizer. Baseline playback solves Kepler anomaly on the circular Hohmann ellipse. Edited sketches use geometric playback, with no physical maneuver solution. Playback lasts 20 seconds.');
 }
 function buildEclipse(){
  const rs=2,rm=.6,ds=12,dm=state.moonDistance;const sun=mesh(new T.SphereGeometry(rs,48,32),0xffd59a);sun.material=new T.MeshBasicMaterial({color:0xf5cf91});sun.position.set(-ds,0,0);globe=gfx.world(api.planets[2],64);globe.group.scale.setScalar(.55);group.add(globe.group);const moon=mesh(new T.SphereGeometry(rm,40,24),0x9c9a90);moon.name='eclipse-moon';moon.position.set(-dm,state.offset,0);
  const umbraLength=rm*(ds-dm)/(rs-rm),axis=new T.Vector3(dm,-state.offset,0).normalize(),apex=moon.position.clone().addScaledVector(axis,umbraLength);const cone=new T.Mesh(new T.ConeGeometry(rm,umbraLength,64,1,true),new T.MeshBasicMaterial({color:0x8e9aaf,transparent:true,opacity:.14,depthWrite:false,side:T.DoubleSide}));cone.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),axis);cone.position.copy(moon.position).add(apex).multiplyScalar(.5);group.add(cone);
  for(const z of [-1,1]){line([new T.Vector3(-ds,rs,0),moon.position.clone().add(new T.Vector3(0,z*rm,0)),new T.Vector3(3,state.offset+(3+dm)*(z*rm-rs)/(ds-dm),0)],0x8c8c7d)}
  const result=eclipseState(rs,rm,ds,dm,state.offset);readout([['OBSERVER EVENT',result.type],['SOLAR DISK OBSCURED',fmt(obscuration(result.sun,result.moon,result.separation)*100,1)+'%'],['SUN ANGULAR RADIUS',fmt(result.sun*180/Math.PI,2)+'°'],['MOON ANGULAR RADIUS',fmt(result.moon*180/Math.PI,2)+'°'],['AXIS SEPARATION',fmt(result.separation*180/Math.PI,2)+'°'],['UMBRA LENGTH',fmt(umbraLength)+' scene units']], 'Scaled geometry, not an Earth eclipse prediction. Angular classification is for the reference observer at the origin. The observer camera shares that point; Earth is hidden in this view. The translucent cone marks umbra; boundary rays illustrate penumbra geometry.');
 }
 controls.addEventListener('input',e=>{const id=e.target.id,v=+e.target.value;if(id==='expedition-world'){api.selectPlanet(v);return;}if(id==='surface-sun'){state.sunElevation=v;return;}if(id==='interior-explode'||id==='interior-opacity'){state[id==='interior-explode'?'explode':'opacity']=v;updateInterior();return;}if(id==='landing-lat'||id==='landing-lon'){state[id==='landing-lat'?'lat':'lon']=v;build()}if(id==='surface-x'||id==='surface-z'){state[id==='surface-x'?'x':'z']=v;updateSurface()}if(id==='interior-slice'){state.slice=v;updateInterior()}if(id==='interior-layer'){state.layer=v;updateInterior()}if(id.startsWith('mission-')){const key=({ 'mission-from':'departure','mission-to':'arrival','mission-bend':'bend','mission-height':'height','mission-isp':'isp','mission-dry-mass':'dryMass'})[id];if(key)state[key]=v;if(id==='mission-date'&&e.target.value)state.date=e.target.value;build()}if(id.startsWith('eclipse-')&&id!=='eclipse-camera'){state[id==='eclipse-offset'?'offset':'moonDistance']=v;build()}});
 controls.addEventListener('change',e=>{if(e.target.id==='surface-camera')state.view=e.target.value;if(e.target.id==='eclipse-camera')state.observer=e.target.value==='observer'});
 controls.addEventListener('click',e=>{const id=e.target.id;if(e.target.dataset.drive){const d=e.target.dataset.drive;state.x=clamp(state.x+(d==='east'?.4:d==='west'?-.4:0),-8,8);state.z=clamp(state.z+(d==='south'?.4:d==='north'?-.4:0),-8,8);$('#surface-x').value=state.x;$('#surface-z').value=state.z;updateSurface();}if(id==='mission-scan'){const start=dateDays(state.date),r1=orbitalElements(state.departure)[0],r2=orbitalElements(state.arrival)[0],h=hohmann(r1,r2);let best=start,miss=Infinity;for(let step=0;step<=780;step+=5){const a=position(state.departure,start+step),theta=Math.atan2(a.z,a.x),b=position(state.arrival,start+step+h.seconds/86400),error=Math.hypot(b.x+Math.cos(theta)*r2,b.y,b.z+Math.sin(theta)*r2);if(error<miss){miss=error;best=start+step;}}state.date=new Date(Date.UTC(2000,0,1,12)+best*864e5).toISOString().slice(0,10);$('#mission-date').value=state.date;build();}if(id==='begin-descent'){if(api.getState().current>3){$('#expedition-status').textContent='SELECT A ROCKY WORLD FOR LANDING';return;}document.dispatchEvent(new CustomEvent('orbital-descent',{detail:{lat:state.lat,lon:state.lon}}));$('#explore').scrollIntoView();}if(id==='surface-drive'){running=true;$('#expedition-play').setAttribute('aria-pressed',true)}if(id==='mission-baseline'){state.bend=state.height=0;renderControls()}if(id==='eclipse-total'||id==='eclipse-annular'){state.offset=0;state.moonDistance=id==='eclipse-total'?3:5;renderControls()}});
 document.querySelectorAll('[data-expedition]').forEach(b=>b.onclick=()=>{mode=b.dataset.expedition;state.observer=false;document.querySelectorAll('[data-expedition]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderControls()});
 $('#expedition-reset').onclick=()=>{state.observer=false;state.view='drone';nav?.reset();if($('#surface-camera'))$('#surface-camera').value='drone';if($('#eclipse-camera'))$('#eclipse-camera').value='geometry'};
 $('#expedition-play').onclick=e=>{running=!running;e.currentTarget.setAttribute('aria-pressed',running);e.currentTarget.textContent=running?'Pause experiment':'Play experiment'};
 document.addEventListener('planet-change',()=>{if(mode==='surface'||mode==='interior')renderControls()});
 if(renderer){const ray=new T.Raycaster(),pointer=new T.Vector2(),plane=new T.Plane(new T.Vector3(0,1,0),0);root.addEventListener('pointerdown',e=>{if(mode!=='mission'||!handle)return;const r=root.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);dragging=ray.intersectObject(handle).length>0;if(dragging){root.setPointerCapture(e.pointerId);e.stopImmediatePropagation();}},true);root.addEventListener('pointermove',e=>{if(!dragging)return;const r=root.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.ray.intersectPlane(plane,new T.Vector3());if(hit){const p=position(state.departure,dateDays(state.date)),angle=Math.atan2(p.z,p.x),local=hit.clone().applyAxisAngle(new T.Vector3(0,1,0),angle);state.bend=clamp(local.x,-3,3);$('#mission-bend').value=state.bend;buildMissionOnly()}e.stopImmediatePropagation()},true);root.addEventListener('pointerup',()=>dragging=false);root.addEventListener('pointercancel',()=>dragging=false);renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();renderer=null;root.innerHTML='<p class="fallback-message">Graphics context lost. Numerical controls remain usable.</p>'})}
 function buildMissionOnly(){dispose();buildMission()}
 new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(section);
 function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05)||0;last=now;if(!visible||document.hidden||!renderer)return;if(api.getState().motion)visualTime+=dt;nav.update(dt,api.getState().motion);if(running&&api.getState().motion){elapsed+=dt;phase=(phase+dt/20)%1;if(mode==='surface'&&rover){state.x=clamp(state.x+dt*.4,-8,8);$('#surface-x').value=state.x;updateSurface()}if(mode==='interior'){state.slice=Math.sin(elapsed*.3)*.85;$('#interior-slice').value=state.slice;updateInterior()}if(mode==='mission'&&curve)craft.position.copy(curve.getPoint(phase));if(mode==='eclipse'&&Math.floor(elapsed*8)!==Math.floor((elapsed-dt)*8)){state.offset=Math.sin(elapsed*.35)*1.8;$('#eclipse-offset').value=state.offset;dispose();buildEclipse()}}
  if(mode==='surface'&&rover){const elevation=state.sunElevation*Math.PI/180;keyLight.position.set(-Math.cos(elevation)*20,Math.sin(elevation)*25,8);keyLight.target.position.set(state.x,0,state.z);surfaceExtras?.update(rover,visualTime,{scan:$('#surface-lidar')?.checked,showRocks:$('#surface-rocks')?.checked,showTracks:$('#surface-tracks')?.checked,headlight:$('#surface-lights')?.checked});}if(mode==='surface'&&state.view==='rover'&&rover){camera.position.set(state.x,surfaceHeight(state.x,state.z,seed)+.35,state.z+.5);camera.lookAt(state.x,surfaceHeight(state.x,state.z-4,seed)+.4,state.z-4)}if(mode==='eclipse'){group.traverse(o=>{if(o.isLine)o.visible=!state.observer});const moon=group.getObjectByName('eclipse-moon');if(moon)moon.material.color.setHex(state.observer?0x080808:0x9c9a90);}if(mode==='eclipse'&&state.observer){globe.group.visible=false;camera.position.set(0,0,0);camera.up.set(0,1,0);camera.lookAt(-12,0,0)}else if(mode==='eclipse'&&globe)globe.group.visible=true;renderer.render(scene,camera);
 }document.querySelectorAll('[data-expedition]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.expedition===mode));renderControls();if(location.hash==='#expeditions')section.scrollIntoView();requestAnimationFrame(frame);
}
